// === Tab: mySketch ===
let seed = Math.random() * 9999;
let num = 3;
let radius, mySize;
let v_planet = [];
let trails = [];
let t = 0;
let colors;
let bgColor;

function setup() {
	randomSeed(seed);
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(RADIANS);
	mySize = max(windowWidth, windowHeight);
	radius = mySize * 0.75;

	// 简单色彩方案
	colors = random(colorScheme).colors;
	bgColor = color(10, 5, 20);
	background(bgColor);

	for (let i = 0; i < num; i++) {
		trails.push([]);
	}
}

function draw() {
	randomSeed(seed);
	background(bgColor);
	// 摄像机缓慢围绕中心旋转
	let camX = sin(t * 0.2) * radius * 1.5;
	let camY = cos(t * 0.15) * radius * 0.6;
	let camZ = cos(t * 0.25) * radius * 1.5;
	camera(camX, camY, camZ, 0, 0, 0, 0, 1, 0);
	// rotateX(PI / 2);
	rotateX(random(TAU));
	rotateY(random(TAU));
	rotateZ(random(TAU));

	let layerCount = 1;
	let R = radius * 0.25;

	// 更新轨迹
	for (let i = 0; i < num; i++) {
		let layer = i % layerCount;
		let layerAngleOffset = (TWO_PI / layerCount) * layer;
		let baseAngle = (TWO_PI / num) * i + t * 0.5;

		let spiralRadius = R * (1 + 0.6 * sin(t + i * 2));
		let heightOffset = sin(t * 1.2 + i) * radius * 0.4;

		let theta = baseAngle + layerAngleOffset;
		let phi = t + i * 0.3;

		let x = spiralRadius * sin(theta) * cos(phi);
		let y = spiralRadius * sin(theta) * sin(phi);
		let z = spiralRadius * cos(theta) + heightOffset;

		let p = createVector(x, y, z);
		v_planet[i] = p;
		trails[i].push(p.copy());

		if (trails[i].length > 50) trails[i].shift();
	}

	// 多重对称结构（6组）
	for (let s = 0; s < 6; s++) {
		push();
		rotateX((TWO_PI / 6) * s);
		drawTrailsAndPlanets();
		pop();
	}

	t += 0.1;
}

function drawTrailsAndPlanets() {
	for (let i = 0; i < num; i++) {
		for (let j = 1; j < trails[i].length; j++) {
			let p1 = trails[i][j - 1];
			let p2 = trails[i][j];

			let progress = j / trails[i].length;
			let baseSW = sin(progress * PI) * 12;

			let c = color(colors[i % colors.length]);
			c.setAlpha(map(progress, 0, 1, 150, 255));

			// 主线
			stroke(c);
			strokeWeight(baseSW);
			line(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);

			// 残影（彩色拖尾）
			for (let k = 0; k < 1; k++) {
				let offset = p5.Vector.random3D().mult(4 + k * 2);
				let c2 = color(colors[(i + k + 1) % colors.length]);
				c2.setAlpha(c._getAlpha() * 1.3);
				stroke(c2);
				strokeWeight(baseSW * 0.4);
				line(p1.x + offset.x, p1.y + offset.y, p1.z + offset.z,
					p2.x + offset.x, p2.y + offset.y, p2.z + offset.z);
			}
		}

		// 小球（行星）
		push();
		var p = v_planet[i];
		translate(p.x, p.y, p.z);
		fill(colors[i % colors.length]);
		noStroke();
		sphere(3 + 3 * sin(t * 3 + i));
		pop();
	}
}

